{
  "name": "verify-signed-commits-action",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test.js"
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";

import {
  buildAgentPrompt,
  buildFailureComment,
  COMMENT_MARKER,
  findUnsignedCommits,
  verifySignedCommits,
} from "./index.js";

const REPO = "vercel/streamdown";

function makeCommit(sha, { verified, reason, message = "feat: thing" }) {
  return {
    sha,
    author: { login: "octocat" },
    commit: {
      message,
      author: { name: "Octo Cat" },
      verification: { verified, reason },
    },
  };
}

function makeEvent() {
  return {
    pull_request: {
      number: 42,
      base: { ref: "main" },
      head: { sha: "abcdef1234567890" },
    },
  };
}

function makeGitHub({ commits, comments = [] }) {
  const calls = [];
  return {
    calls,
    paginate(path) {
      calls.push(["GET", path]);
      if (path.endsWith("/commits")) {
        return Promise.resolve(commits);
      }
      return Promise.resolve(comments);
    },
    request(method, path, body) {
      calls.push([method, path, body]);
      return Promise.resolve({});
    },
  };
}

const signed = makeCommit("1111111aaaa", { verified: true, reason: "valid" });
const unsigned = makeCommit("2222222bbbb", {
  verified: false,
  reason: "unsigned",
  message: "fix: oops\n\nbody text",
});
const unknownKey = makeCommit("3333333cccc", {
  verified: false,
  reason: "unknown_key",
});

test("findUnsignedCommits returns only unverified commits", () => {
  const result = findUnsignedCommits([signed, unsigned, unknownKey]);
  assert.deepStrictEqual(
    result.map((c) => [c.sha, c.subject, c.reason]),
    [
      ["2222222bbbb", "fix: oops", "unsigned"],
      ["3333333cccc", "feat: thing", "unknown_key"],
    ]
  );
  assert.ok(result[1].hint.includes("not added"));
});

test("findUnsignedCommits treats missing verification as unsigned", () => {
  const result = findUnsignedCommits([{ sha: "444", commit: {} }]);
  assert.strictEqual(result.length, 1);
  assert.strictEqual(result[0].reason, "unsigned");
});

test("failure comment lists commits, fix steps and agent prompt", () => {
  const body = buildFailureComment({
    unsigned: findUnsignedCommits([unsigned]),
    total: 2,
    repository: REPO,
    baseRef: "main",
    headSha: "abcdef1234567890",
  });
  assert.ok(body.startsWith(COMMENT_MARKER));
  assert.ok(body.includes("**1 of 2**"));
  assert.ok(body.includes("`2222222` | fix: oops"));
  assert.ok(body.includes("git config --global commit.gpgsign true"));
  assert.ok(body.includes("git push --force-with-lease"));
  assert.ok(
    body.includes(buildAgentPrompt({ repository: REPO, baseRef: "main" }))
  );
});

test("failure comment escapes table-breaking characters and mentions", () => {
  const body = buildFailureComment({
    unsigned: findUnsignedCommits([
      makeCommit("5555555", {
        verified: false,
        reason: "unsigned",
        message: "a | b @someone <img>",
      }),
    ]),
    total: 1,
    repository: REPO,
    baseRef: "main",
    headSha: "abcdef1",
  });
  assert.ok(body.includes("a \\| b @\u200bsomeone &lt;img>"));
});

test("creates a comment and fails when commits are unsigned", async () => {
  const github = makeGitHub({ commits: [signed, unsigned] });
  const result = await verifySignedCommits(makeEvent(), github, REPO);

  assert.strictEqual(result.ok, false);
  const post = github.calls.find(([m]) => m === "POST");
  assert.strictEqual(post[1], `/repos/${REPO}/issues/42/comments`);
  assert.ok(post[2].body.includes("Unsigned commits found"));
});

test("updates the existing bot comment instead of posting a new one", async () => {
  const github = makeGitHub({
    commits: [unsigned],
    comments: [
      { id: 7, user: { type: "User" }, body: COMMENT_MARKER },
      { id: 9, user: { type: "Bot" }, body: `${COMMENT_MARKER}\nold` },
    ],
  });
  await verifySignedCommits(makeEvent(), github, REPO);

  assert.ok(!github.calls.some(([m]) => m === "POST"));
  const patch = github.calls.find(([m]) => m === "PATCH");
  assert.strictEqual(patch[1], `/repos/${REPO}/issues/comments/9`);
});

test("passes without commenting when all commits are signed", async () => {
  const github = makeGitHub({ commits: [signed] });
  const result = await verifySignedCommits(makeEvent(), github, REPO);

  assert.strictEqual(result.ok, true);
  assert.ok(!github.calls.some(([m]) => m === "POST" || m === "PATCH"));
});

test("marks a previous failure comment as resolved once fixed", async () => {
  const github = makeGitHub({
    commits: [signed],
    comments: [{ id: 9, user: { type: "Bot" }, body: COMMENT_MARKER }],
  });
  await verifySignedCommits(makeEvent(), github, REPO);

  const patch = github.calls.find(([m]) => m === "PATCH");
  assert.ok(patch[2].body.includes("All commits are signed"));
});

import assert from "node:assert/strict";
import { mock, test } from "node:test";

import { verifyChangesets } from "./index.js";

test("happy path", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/some-happy-path.md",
  };

  const readFile = mock.fn(
    async (_path) =>
      "---\nai: patch\n@ai-sdk/provider: patch\n---\n## Test changeset"
  );

  await verifyChangesets(event, env, readFile);

  assert.strictEqual(readFile.mock.callCount(), 1);
  assert.deepStrictEqual(readFile.mock.calls[0].arguments, [
    "../../../../.changeset/some-happy-path.md",
    "utf-8",
  ]);
});

test("allows numbers in changeset filename", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/fix-icons-aria-hidden.md",
  };

  const readFile = mock.fn(
    async (_path) =>
      "---\nai: patch\n@ai-sdk/provider: patch\n---\n## Test changeset"
  );

  await verifyChangesets(event, env, readFile);

  assert.strictEqual(readFile.mock.callCount(), 1);
  assert.deepStrictEqual(readFile.mock.calls[0].arguments, [
    "../../../../.changeset/fix-icons-aria-hidden.md",
    "utf-8",
  ]);
});

test("ignores .changeset/README.md", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/README.md",
  };

  const readFile = mock.fn(() => {
    // Intentionally empty for testing ignore behavior
  });

  await verifyChangesets(event, env, readFile);

  assert.strictEqual(readFile.mock.callCount(), 0);
});

test("invalid file - not a .changeset file", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/not-a-changeset-file.txt",
  };

  const readFile = mock.fn(() => {
    // Intentionally empty for testing validation error
  });

  await assert.rejects(
    () => verifyChangesets(event, env, readFile),
    Object.assign(new Error("Invalid file - not a .changeset file"), {
      path: ".changeset/not-a-changeset-file.txt",
    })
  );

  assert.strictEqual(readFile.mock.callCount(), 0);
});

test("invalid .changeset file - no frontmatter", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/invalid-changeset-file.md",
  };

  const readFile = mock.fn(async (_path) => "frontmatter missing");
  await assert.rejects(
    () => verifyChangesets(event, env, readFile),
    Object.assign(new Error("Invalid .changeset file - no frontmatter found"), {
      path: ".changeset/invalid-changeset-file.md",
      content: "frontmatter missing",
    })
  );
  assert.strictEqual(readFile.mock.callCount(), 1);
  assert.deepStrictEqual(readFile.mock.calls[0].arguments, [
    "../../../../.changeset/invalid-changeset-file.md",
    "utf-8",
  ]);
});

test("invalid .changeset file - invalid frontmatter", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/invalid-frontmatter.md",
  };

  // "ai patch" has no colon, so it has no version bump to read.
  const content = "---\nai patch\n---\n## Test changeset";
  const readFile = mock.fn(async (_path) => content);

  await assert.rejects(
    () => verifyChangesets(event, env, readFile),
    Object.assign(new Error("Invalid .changeset file - invalid frontmatter"), {
      path: ".changeset/invalid-frontmatter.md",
      content,
    })
  );
  assert.strictEqual(readFile.mock.callCount(), 1);
});

test("minor update", async () => {
  const event = {
    pull_request: {
      labels: [],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/patch-update.md .changeset/minor-update.md",
  };

  const readFile = mock.fn((path) => {
    if (path.endsWith("patch-update.md")) {
      return Promise.resolve("---\nai: patch\n---\n## Test changeset");
    }

    return Promise.resolve(
      "---\n@ai-sdk/provider: minor\n---\n## Test changeset"
    );
  });

  await assert.rejects(
    () => verifyChangesets(event, env, readFile),
    Object.assign(
      new Error(
        `Invalid .changeset file - invalid version bump (only "patch" is allowed, see https://ai-sdk.dev/docs/migration-guides/versioning). To bypass, add one of the following labels: minor, major`
      ),
      {
        path: ".changeset/minor-update.md",
        content: "---\n@ai-sdk/provider: minor\n---\n## Test changeset",
      }
    )
  );

  assert.strictEqual(readFile.mock.callCount(), 2);
  assert.deepStrictEqual(readFile.mock.calls[0].arguments, [
    "../../../../.changeset/patch-update.md",
    "utf-8",
  ]);
  assert.deepStrictEqual(readFile.mock.calls[1].arguments, [
    "../../../../.changeset/minor-update.md",
    "utf-8",
  ]);
});

test('minor update - with "minor" label', async () => {
  const event = {
    pull_request: {
      labels: [
        {
          name: "minor",
        },
      ],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/patch-update.md .changeset/minor-update.md",
  };

  const readFile = mock.fn((path) => {
    if (path.endsWith("patch-update.md")) {
      return Promise.resolve("---\nai: patch\n---\n## Test changeset");
    }

    return Promise.resolve(
      "---\n@ai-sdk/provider: minor\n---\n## Test changeset"
    );
  });

  const message = await verifyChangesets(event, env, readFile);
  assert.strictEqual(
    message,
    'Skipping changeset verification - "minor" label found'
  );
});

test('major update - with "major" label', async () => {
  const event = {
    pull_request: {
      labels: [
        {
          name: "major",
        },
      ],
    },
  };
  const env = {
    CHANGED_FILES: ".changeset/patch-update.md .changeset/major-update.md",
  };

  const readFile = mock.fn((path) => {
    if (path.endsWith("patch-update.md")) {
      return Promise.resolve("---\nai: patch\n---\n## Test changeset");
    }

    return Promise.resolve(
      "---\n@ai-sdk/provider: major\n---\n## Test changeset"
    );
  });

  const message = await verifyChangesets(event, env, readFile);
  assert.strictEqual(
    message,
    'Skipping changeset verification - "major" label found'
  );
});

import fs from "node:fs/promises";

const BYPASS_LABELS = ["minor", "major"];

// Regex patterns moved to top level for performance
const CHANGESET_FILE_PATTERN = /^\.changeset\/[a-z0-9-]+\.md/;
const FRONTMATTER_PATTERN = /---\n([\s\S]+?)\n---/;

// Helper function to validate changeset file path
function validateChangesetPath(path) {
  if (!CHANGESET_FILE_PATTERN.test(path)) {
    throw Object.assign(new Error("Invalid file - not a .changeset file"), {
      path,
    });
  }
}

// Helper function to extract frontmatter from content
function extractFrontmatter(content, path) {
  const result = content.match(FRONTMATTER_PATTERN);
  if (!result) {
    throw Object.assign(
      new Error("Invalid .changeset file - no frontmatter found"),
      { path, content }
    );
  }
  return result[0];
}

// Helper function to parse version bumps from frontmatter
function parseVersionBumps(frontmatter, path, content) {
  const lines = frontmatter.split("\n").slice(1, -1);
  const versionBumps = {};

  for (const line of lines) {
    const [packageName, versionBump] = line.split(":").map((s) => s.trim());
    if (!(packageName && versionBump)) {
      throw Object.assign(
        new Error("Invalid .changeset file - invalid frontmatter"),
        {
          path,
          content,
        }
      );
    }

    // Check if packageName is already set
    if (versionBumps[packageName]) {
      throw Object.assign(
        new Error(
          `Invalid .changeset file - duplicate package name "${packageName}"`
        ),
        { path, content }
      );
    }

    versionBumps[packageName] = versionBump;
  }

  return versionBumps;
}

// Helper function to validate version bumps
function validateVersionBumps(versionBumps, path, content) {
  const invalidVersionBumps = Object.entries(versionBumps).filter(
    ([, versionBump]) => versionBump !== "patch"
  );

  if (invalidVersionBumps.length > 0) {
    throw Object.assign(
      new Error(
        `Invalid .changeset file - invalid version bump (only "patch" is allowed, see https://ai-sdk.dev/docs/migration-guides/versioning). To bypass, add one of the following labels: ${BYPASS_LABELS.join(", ")}`
      ),
      { path, content }
    );
  }
}

// check if current file is the entry point
if (import.meta.url.endsWith(process.argv[1])) {
  // https://docs.github.com/en/webhooks/webhook-events-and-payloads#pull_request
  const pullRequestEvent = JSON.parse(
    await fs.readFile(process.env.GITHUB_EVENT_PATH, "utf-8")
  );

  try {
    const message = await verifyChangesets(
      pullRequestEvent,
      process.env,
      fs.readFile
    );
    await fs.writeFile(
      process.env.GITHUB_STEP_SUMMARY,
      `## Changeset verification passed ✅\n\n${message || ""}`
    );
  } catch (error) {
    await fs.writeFile(
      process.env.GITHUB_STEP_SUMMARY,
      `## Changeset verification failed ❌

${error.message}`
    );

    if (error.path) {
      await fs.appendFile(
        process.env.GITHUB_STEP_SUMMARY,
        `\n\nFile: \`${error.path}\``
      );
    }

    if (error.content) {
      await fs.appendFile(
        process.env.GITHUB_STEP_SUMMARY,
        `\n\n\`\`\`yaml\n${error.content}\n\`\`\``
      );
    }

    process.exit(1);
  }
}

export async function verifyChangesets(
  event,
  env = process.env,
  readFile = fs.readFile
) {
  // Skip check if pull request carries one of the bypass labels
  const byPassLabel = event.pull_request.labels.find((label) =>
    BYPASS_LABELS.includes(label.name)
  );
  if (byPassLabel) {
    return `Skipping changeset verification - "${byPassLabel.name}" label found`;
  }

  // Iterate through all changed .changeset/*.md files
  for (const path of env.CHANGED_FILES.trim().split(" ")) {
    // ignore README.md file
    if (path === ".changeset/README.md") {
      continue;
    }

    // Validate path
    validateChangesetPath(path);

    // Read and parse changeset file
    const content = await readFile(`../../../../${path}`, "utf-8");
    const frontmatter = extractFrontmatter(content, path);
    const versionBumps = parseVersionBumps(frontmatter, path, content);

    // Validate version bumps
    validateVersionBumps(versionBumps, path, content);
  }
}

import fs from "node:fs/promises";

export const COMMENT_MARKER = "<!-- verify-signed-commits -->";

const API_URL = process.env.GITHUB_API_URL || "https://api.github.com";
const MAX_LISTED_COMMITS = 50;
const SIGNING_DOCS_URL =
  "https://docs.github.com/en/authentication/managing-commit-signature-verification";

// Human-friendly explanations for `commit.verification.reason`
// https://docs.github.com/en/rest/commits/commits#signature-verification-object
const REASON_HINTS = {
  unsigned: "commit is not signed",
  unknown_key: "signing key is not added to the author's GitHub account",
  not_signing_key:
    "key is on GitHub as an authentication key, not as a signing key",
  bad_email: "author email does not match an email on the signing key",
  unverified_email: "author email is not verified on GitHub",
  no_user: "author email is not associated with any GitHub account",
  expired_key: "signing key has expired",
  invalid: "signature is invalid",
  malformed_signature: "signature could not be parsed",
  unknown_signature_type: "unsupported signature type",
  bad_cert: "signing certificate is invalid",
  gpgverify_error: "GitHub could not verify the signature, try again later",
  gpgverify_unavailable:
    "GitHub could not verify the signature, try again later",
  ocsp_pending: "certificate revocation check is pending, try again later",
  ocsp_error: "certificate revocation check failed",
  ocsp_revoked: "signing certificate has been revoked",
};

export function findUnsignedCommits(commits) {
  return commits
    .filter((c) => !c.commit?.verification?.verified)
    .map((c) => {
      const reason = c.commit?.verification?.reason || "unsigned";
      return {
        sha: c.sha,
        subject: (c.commit?.message || "").split("\n")[0],
        author: c.author?.login || c.commit?.author?.name || "unknown",
        reason,
        hint: REASON_HINTS[reason] || reason,
      };
    });
}

// Keep commit subjects from breaking out of the markdown table or pinging users
function escapeCell(text) {
  return text
    .replaceAll("|", "\\|")
    .replaceAll("@", "@\u200b")
    .replaceAll("<", "&lt;");
}

export function buildAgentPrompt({ repository, baseRef }) {
  return `My pull request to ${repository} is blocked because some commits are not signed with a verified signature. Please help me fix it:

1. Check whether commit signing is already configured: \`git config --get gpg.format\`, \`git config --get user.signingkey\`, \`git config --get commit.gpgsign\`, and \`git config --get user.email\`.
2. If signing is not configured, set up SSH commit signing: reuse an existing key in ~/.ssh (for example id_ed25519.pub) or generate one with \`ssh-keygen -t ed25519 -C "<my email>"\`, then run \`git config --global gpg.format ssh\`, \`git config --global user.signingkey <path to the .pub file>\`, and \`git config --global commit.gpgsign true\`.
3. Tell me to add the public key on GitHub at https://github.com/settings/ssh/new with "Key type" set to "Signing Key" (if \`gh\` is installed and authenticated with the admin:ssh_signing_key scope, you may run \`gh ssh-key add <path to .pub> --type signing\` instead). Also confirm that \`git config user.email\` is a verified email on my GitHub account (https://github.com/settings/emails). Wait for me to confirm before continuing.
4. Re-sign every commit on my branch without changing its content: fetch ${baseRef} from https://github.com/${repository}.git, then run \`git rebase --exec 'git commit --amend --no-edit --no-verify -S' $(git merge-base HEAD FETCH_HEAD)\`. Do not rebase onto a newer ${baseRef}, and do not squash, reorder, or edit commits.
5. Verify with \`git log --show-signature FETCH_HEAD..HEAD\` that every commit shows a good signature.
6. Ask me before running \`git push --force-with-lease\` to update the pull request branch.`;
}

export function buildFailureComment({
  unsigned,
  total,
  repository,
  baseRef,
  headSha,
}) {
  const rows = unsigned
    .slice(0, MAX_LISTED_COMMITS)
    .map(
      (c) =>
        `| \`${c.sha.slice(0, 7)}\` | ${escapeCell(c.subject)} | ${escapeCell(c.author)} | ${c.hint} |`
    );
  if (unsigned.length > MAX_LISTED_COMMITS) {
    rows.push(`| … | _and ${unsigned.length - MAX_LISTED_COMMITS} more_ | | |`);
  }

  return `${COMMENT_MARKER}
## ❌ Unsigned commits found

**${unsigned.length} of ${total}** commit(s) in this pull request do not have a verified signature. All commits must be signed before this PR can be merged.

| Commit | Subject | Author | Reason |
| --- | --- | --- | --- |
${rows.join("\n")}

### How to fix

**1. Set up commit signing** (one-time; SSH shown, [GPG and S/MIME also work](${SIGNING_DOCS_URL})):

\`\`\`sh
git config --global gpg.format ssh
git config --global user.signingkey ~/.ssh/id_ed25519.pub
git config --global commit.gpgsign true
\`\`\`

**2. Add the key to GitHub as a _Signing Key_** at [github.com/settings/ssh/new](https://github.com/settings/ssh/new) (an authentication key alone is not enough), and make sure your \`git config user.email\` is a [verified email](https://github.com/settings/emails) on your account.

**3. Re-sign the commits on this branch and force-push:**

\`\`\`sh
git fetch https://github.com/${repository}.git ${baseRef}
git rebase --exec 'git commit --amend --no-edit --no-verify -S' $(git merge-base HEAD FETCH_HEAD)
git push --force-with-lease
\`\`\`

This check re-runs automatically when you push. See [CONTRIBUTING.md](https://github.com/${repository}/blob/${baseRef}/CONTRIBUTING.md#signing-commits) for more details.

<details>
<summary>🤖 Using an AI coding agent? Paste this prompt</summary>

\`\`\`text
${buildAgentPrompt({ repository, baseRef })}
\`\`\`

</details>

<sub>Checked at ${headSha.slice(0, 7)}.</sub>
`;
}

export function buildSuccessComment({ total, headSha }) {
  return `${COMMENT_MARKER}
## ✅ All commits are signed

All ${total} commit(s) in this pull request have a verified signature. Thanks!

<sub>Checked at ${headSha.slice(0, 7)}.</sub>
`;
}

export function createGitHubClient(token, fetchImpl = fetch) {
  async function request(method, path, body) {
    const response = await fetchImpl(`${API_URL}${path}`, {
      method,
      headers: {
        Accept: "application/vnd.github+json",
        Authorization: `Bearer ${token}`,
        "X-GitHub-Api-Version": "2022-11-28",
        ...(body ? { "Content-Type": "application/json" } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    if (!response.ok) {
      throw new Error(
        `GitHub API ${method} ${path} failed: ${response.status} ${await response.text()}`
      );
    }
    return response.json();
  }

  async function paginate(path) {
    const results = [];
    for (let page = 1; ; page++) {
      const separator = path.includes("?") ? "&" : "?";
      const items = await request(
        "GET",
        `${path}${separator}per_page=100&page=${page}`
      );
      results.push(...items);
      if (items.length < 100) {
        return results;
      }
    }
  }

  return { request, paginate };
}

async function upsertComment(github, { repository, prNumber, body, create }) {
  const comments = await github.paginate(
    `/repos/${repository}/issues/${prNumber}/comments`
  );
  const existing = comments.find(
    (c) => c.user?.type === "Bot" && c.body?.includes(COMMENT_MARKER)
  );

  if (existing) {
    await github.request(
      "PATCH",
      `/repos/${repository}/issues/comments/${existing.id}`,
      { body }
    );
    return "updated";
  }
  if (create) {
    await github.request(
      "POST",
      `/repos/${repository}/issues/${prNumber}/comments`,
      { body }
    );
    return "created";
  }
  return "skipped";
}

export async function verifySignedCommits(event, github, repository) {
  const pr = event.pull_request;
  const commits = await github.paginate(
    `/repos/${repository}/pulls/${pr.number}/commits`
  );
  const unsigned = findUnsignedCommits(commits);
  const context = {
    unsigned,
    total: commits.length,
    repository,
    baseRef: pr.base.ref,
    headSha: pr.head.sha,
  };

  if (unsigned.length > 0) {
    await upsertComment(github, {
      repository,
      prNumber: pr.number,
      body: buildFailureComment(context),
      create: true,
    });
    return { ok: false, ...context };
  }

  // Only flip an existing failure comment to green; don't comment on clean PRs.
  await upsertComment(github, {
    repository,
    prNumber: pr.number,
    body: buildSuccessComment(context),
    create: false,
  });
  return { ok: true, ...context };
}

// check if current file is the entry point
if (import.meta.url.endsWith(process.argv[1])) {
  const event = JSON.parse(
    await fs.readFile(process.env.GITHUB_EVENT_PATH, "utf-8")
  );
  const github = createGitHubClient(process.env.GITHUB_TOKEN);
  const result = await verifySignedCommits(
    event,
    github,
    process.env.GITHUB_REPOSITORY
  );

  if (result.ok) {
    await fs.writeFile(
      process.env.GITHUB_STEP_SUMMARY,
      `## Signed commits verification passed ✅\n\nAll ${result.total} commit(s) are signed.\n`
    );
  } else {
    await fs.writeFile(
      process.env.GITHUB_STEP_SUMMARY,
      buildFailureComment(result)
    );
    for (const c of result.unsigned) {
      console.error(
        `::error title=Unsigned commit::${c.sha.slice(0, 7)} ${c.subject} (${c.hint})`
      );
    }
    process.exit(1);
  }
}

